import { expect, test, uniqueName } from "../../fixtures";

test.describe("Upload vendor documents", () => {
  test(
    "A file of exactly 10 MiB is accepted",
    { tag: "@DOC-05" },
    async ({ apiAs }) => {
      // Arrange: a signed-in member and a vendor in status "draft"
      const member = await apiAs("member");
      const vendorResponse = await member.post("/api/vendors", {
        data: {
          name: uniqueName("DOC-05 Vendor"),
          category: "services",
          contact_email: `doc05.${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}@example.test`,
        },
      });
      expect(vendorResponse.status()).toBe(201);
      const vendor = await vendorResponse.json();
      expect(vendor.status).toBe("draft");

      // Arrange: a text file of exactly 10 MiB (10 * 1024 * 1024 bytes)
      const tenMiB = 10 * 1024 * 1024;
      const buffer = Buffer.alloc(tenMiB, "a");

      // Act
      const response = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "contract",
          file: {
            name: "contract-10mib.txt",
            mimeType: "text/plain",
            buffer,
          },
        },
      });

      // Assert
      expect(response.status()).toBe(201);
    },
  );
});
